<?php
declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Garrison\OperationalCustodyTransitionService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Input\InputOption;use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:garrison:transition-operational-custody',description:'Consume one exact deployment authorization and record bounded operational custody.')]
final class GarrisonTransitionOperationalCustodyCommand extends Command{public function __construct(private readonly OperationalCustodyTransitionService$s){parent::__construct();}protected function configure():void{$this->addArgument('authorization-id',InputArgument::REQUIRED)->addArgument('constable-binding-id',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->s->transition((string)$i->getArgument('authorization-id'),(string)$i->getArgument('constable-binding-id'));}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}$o->writeln($i->getOption('json')?json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR):'<info>OPERATIONAL_CUSTODY_TRANSITIONED</info> '.$r['transition_id']);return self::SUCCESS;}}
